  'rs.facets_help': '复选框列出最常见的值(“排除”让用户改为将其筛除)。范围和“从/到”需要数字或日期列:范围写作 `from..to = label`,以 `;` 分隔,开放的一端留空(`..1000`、`2020-01-01..`);范围包含起点,不包含终点。星级评分提供“4 星及以上”等选项(最多 5;JSON 中的 `"max"` 可更改)。',
